// halftone-portrait.js — Kyle as a newspaper halftone on a 45° screen (~90×120 dots), drawn in WebGL2.
// The glasses resolve first, the face fills in behind them; at rest the dots breathe; the pointer moves
// through them like a stone through water and they spring back. The element carries a still of the
// same halftone as its background (no JS, no WebGL2, before init); init() clears it once the canvas
// owns the box. Reduced motion draws the finished portrait once. Built from Kyle's photo, background
// removed; the tone field below is 180×240 darkness values (0 = paper, 255 = ink), person only.
/* Halftone portrait — Kyle Xu.
   180x240 darkness field (0 = paper, 255 = ink), person only; sampled under each dot of a 45-degree screen. */
const PORTRAIT_TONE = "";

export function init(el) {
  const TW = 180, TH = 240;                    // tone field size
  const DOTS = 10800;                          // ~90 x 120 dots in the 3:4 box
  const EYES = [[0.323, 0.437], [0.635, 0.425]]; // box-normalised eye centres (viewer's left, right)
  const INK = (+(getComputedStyle(el).color.match(/\d+/) || [23])[0]) / 255;   // the page's ink (--fg), read from the element

  // ---------- data ----------
  const bin = atob(PORTRAIT_TONE);
  const tone = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) tone[i] = bin.charCodeAt(i);
  const sampleTone = (u, v) => {             // bilinear, u,v in 0..1
    let x = u * TW - 0.5, y = v * TH - 0.5;
    if (x < -0.5 || y < -0.5 || x > TW - 0.5 || y > TH - 0.5) return 0;
    x = Math.min(TW - 1.001, Math.max(0, x)); y = Math.min(TH - 1.001, Math.max(0, y));
    const x0 = x | 0, y0 = y | 0, fx = x - x0, fy = y - y0, i = y0 * TW + x0;
    return ((tone[i] * (1 - fx) + tone[i + 1] * fx) * (1 - fy) + (tone[i + TW] * (1 - fx) + tone[i + TW + 1] * fx) * fy) / 255;
  };

  // ---------- canvas / GL ----------
  if (getComputedStyle(el).position === 'static') el.style.position = 'relative';
  const cv = document.createElement('canvas');
  cv.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;display:block;touch-action:pan-y;';
  el.appendChild(cv);
  const gl = cv.getContext('webgl2', { antialias: false, alpha: true, premultipliedAlpha: true });
  if (!gl) { cv.remove(); return; }          // the static halftone background stays as the portrait

  const vs = `#version 300 es
  layout(location=0) in vec2 corner;
  layout(location=1) in vec3 dot;            // x, y, r in device px
  uniform vec2 res;
  out vec2 lp; out float rr;
  void main(){
    float e = dot.z + 1.0;
    lp = corner * e; rr = dot.z;
    vec2 p = dot.xy + lp;
    gl_Position = dot.z < 0.03 ? vec4(2.0, 2.0, 2.0, 1.0) : vec4(p / res * vec2(2.0, -2.0) + vec2(-1.0, 1.0), 0.0, 1.0);
  }`;
  const fs = `#version 300 es
  precision highp float;
  in vec2 lp; in float rr;
  uniform float ink;
  out vec4 o;
  void main(){
    float a = clamp(rr - length(lp) + 0.5, 0.0, 1.0);
    // sub-pixel dots: keep their ink equal to their true area instead of a 1px smudge
    if (rr < 1.0) a *= 1.125 * 3.0 * rr * rr / ((rr + 0.5) * (rr + 0.5) * (rr + 0.5));
    if (a <= 0.0) discard;
    o = vec4(vec3(ink) * a, a);
  }`;
  const sh = (t, s) => { const o = gl.createShader(t); gl.shaderSource(o, s); gl.compileShader(o); if (!gl.getShaderParameter(o, gl.COMPILE_STATUS)) throw gl.getShaderInfoLog(o); return o; };
  const prog = gl.createProgram();
  gl.attachShader(prog, sh(gl.VERTEX_SHADER, vs)); gl.attachShader(prog, sh(gl.FRAGMENT_SHADER, fs)); gl.linkProgram(prog);
  gl.useProgram(prog);
  const uRes = gl.getUniformLocation(prog, 'res');
  gl.uniform1f(gl.getUniformLocation(prog, 'ink'), INK);
  const vao = gl.createVertexArray(); gl.bindVertexArray(vao);
  const qb = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER, qb);
  gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 1, -1, -1, 1, 1, 1]), gl.STATIC_DRAW);
  gl.enableVertexAttribArray(0); gl.vertexAttribPointer(0, 2, gl.FLOAT, false, 0, 0);
  const ib = gl.createBuffer(); gl.bindBuffer(gl.ARRAY_BUFFER, ib);
  gl.enableVertexAttribArray(1); gl.vertexAttribPointer(1, 3, gl.FLOAT, false, 0, 0); gl.vertexAttribDivisor(1, 1);
  gl.enable(gl.BLEND); gl.blendFunc(gl.ONE, gl.ONE_MINUS_SRC_ALPHA);
  gl.clearColor(0, 0, 0, 0);
  el.style.backgroundImage = 'none';           // from here the canvas draws the portrait

  // ---------- layout: a 45-degree screen over the 3:4 box ----------
  let N = 0, dpr = 1, W = 0, H = 0, bx = 0, by = 0, bw = 0, bh = 0, pitch = 1;
  let rx, ry, rBase, delay, edx, edy, ox, oy, vx, vy, inst, lit;
  function layout() {
    const r = el.getBoundingClientRect(), nW = Math.max(1, r.width), nH = Math.max(1, r.height), nD = Math.min(2, window.devicePixelRatio || 1);
    if (N && nW === W && nH === H && nD === dpr) return false;   // nothing moved: keep the dots where they are
    W = nW; H = nH; dpr = nD;
    cv.width = Math.round(W * dpr); cv.height = Math.round(H * dpr);
    bw = Math.min(W, H * 0.75); bh = bw / 0.75; bx = (W - bw) / 2; by = (H - bh) / 2;
    pitch = Math.sqrt(bw * bh / DOTS);
    const a = pitch / Math.SQRT2, cx = bw / 2, cy = bh / 2, span = Math.ceil((bw + bh) / pitch) + 2;
    const pts = [];
    for (let j = -span; j <= span; j++) for (let i = -span; i <= span; i++) {
      const x = cx + (i - j) * a, y = cy + (i + j) * a;
      if (x < -pitch * 0.5 || y < -pitch * 0.5 || x > bw + pitch * 0.5 || y > bh + pitch * 0.5) continue;
      pts.push(x, y);
    }
    N = pts.length / 2;
    rx = new Float32Array(N); ry = new Float32Array(N); rBase = new Float32Array(N); delay = new Float32Array(N); lit = new Float32Array(N);
    edx = new Float32Array(N); edy = new Float32Array(N);
    ox = new Float32Array(N); oy = new Float32Array(N); vx = new Float32Array(N); vy = new Float32Array(N);
    inst = new Float32Array(N * 3);
    const speed = bw * 0.72, lensR = bw * 0.165, HOLD = 0.2; // entrance wave speed px/s; glasses radius; the beat on the glasses
    const rMax = pitch * 0.58;                  // darkest cells still keep a pinhole of paper
    for (let k = 0; k < N; k++) {
      const x = pts[2 * k], y = pts[2 * k + 1];
      rx[k] = bx + x; ry[k] = by + y;
      const t = sampleTone(x / bw, y / bh);
      rBase[k] = Math.min(rMax, pitch * Math.sqrt(t / Math.PI));
      let best = 1e9, dx = 0, dy = 0;
      for (const e of EYES) { const ex = x - e[0] * bw, ey = y - e[1] * bh, d = Math.hypot(ex, ey); if (d < best) { best = d; dx = ex; dy = ey; } }
      const n = best || 1; edx[k] = dx / n; edy[k] = dy / n;
      const h = Math.sin(k * 12.9898) * 43758.5453; // tiny jitter so the wavefront is not a ruled line
      // the frames, brows and eyes resolve first, hold a beat, then the wave leaves them
      delay[k] = 0.12 + best / speed + (best > lensR ? HOLD : 0) + (h - Math.floor(h)) * 0.05;
      lit[k] = Math.min(1, rBase[k] / (pitch * 0.12));   // paper (no tone) never lights up
    }
    gl.viewport(0, 0, cv.width, cv.height);
    gl.uniform2f(uRes, cv.width, cv.height);
    gl.bindBuffer(gl.ARRAY_BUFFER, ib); gl.bufferData(gl.ARRAY_BUFFER, inst.byteLength, gl.DYNAMIC_DRAW);
    return true;
  }

  // ---------- pointer: the stone ----------
  const ptr = { in: false, x: 0, y: 0, lx: 0, ly: 0, vx: 0, vy: 0, seen: false, lastRing: -1 };
  const rings = [];                            // {x, y, t0, a}
  function setPtr(e) { const r = el.getBoundingClientRect(); ptr.x = e.clientX - r.left; ptr.y = e.clientY - r.top; if (!ptr.seen) { ptr.lx = ptr.x; ptr.ly = ptr.y; ptr.seen = true; } }
  const onMove = e => { setPtr(e); ptr.in = true; };
  const onLeave = () => { ptr.in = false; ptr.seen = false; };
  const DEBUG_POKE = false, DEBUG_LEAVE = false, DEBUG_WALL = false, DEBUG_FREEZE = 0;   // the prototype's capture hooks, off on the site

  // ---------- simulation ----------
  const K = 140, C = 16;                       // spring, damping (zeta ~0.68: one settle, no wobble)
  let T = 0;                                   // running time (pauses when hidden)
  function step(dt) {
    // pointer kinematics
    if (DEBUG_POKE) {                          // glide in from the left fast, then rest on the viewer's-left eye
      const ex = bx + EYES[0][0] * bw, ey = by + EYES[0][1] * bh;
      if (DEBUG_LEAVE && T > 5.2) { if (ptr.in) onLeave(); }
      else if (T > 3.0) { const u = Math.min(1, (T - 3.0) / 0.45), s = 1 - Math.pow(1 - u, 3); ptr.x = bx - 40 + (ex - bx + 40) * s; ptr.y = ey + 70 * (1 - s); if (!ptr.in) { ptr.lx = ptr.x; ptr.ly = ptr.y; } ptr.in = true; }
    }
    if (ptr.in) {
      const ivx = (ptr.x - ptr.lx) / dt, ivy = (ptr.y - ptr.ly) / dt, s = 1 - Math.exp(-dt * 25);
      ptr.vx += (ivx - ptr.vx) * s; ptr.vy += (ivy - ptr.vy) * s;
      ptr.lx = ptr.x; ptr.ly = ptr.y;
      const sp = Math.hypot(ptr.vx, ptr.vy);
      if (sp > 260 && T - ptr.lastRing > 0.11) { rings.push({ x: ptr.x, y: ptr.y, t0: T, a: Math.min(1, (sp - 200) / 1400) }); ptr.lastRing = T; if (rings.length > 14) rings.shift(); }
    } else { ptr.vx *= 0.8; ptr.vy *= 0.8; }
    while (rings.length && T - rings[0].t0 > RING_LIFE) rings.shift();

    const R = PR(), R2 = R * R;
    const sp = Math.hypot(ptr.vx, ptr.vy);
    const push = 2500 * (0.08 + Math.min(1, sp / 900) * 0.7);   // a resting stone barely parts the dots; a moving one nudges
    const drag = 0.9;
    const px = ptr.x, py = ptr.y, on = ptr.in;
    // active ring fronts (radial kick)
    const fr = [];
    for (const g of rings) { const age = T - g.t0, rad = age * RING_SPEED * bw; fr.push(g.x, g.y, rad, g.a * (1 - age / RING_LIFE) * Math.min(1, rad / (RING_W * 3))); }  // a ring only shoves once it has left the finger
    for (let k = 0; k < N; k++) {
      let ax = -K * ox[k] - C * vx[k], ay = -K * oy[k] - C * vy[k];
      if (on) {
        const dx = rx[k] + ox[k] - px, dy = ry[k] + oy[k] - py, d2 = dx * dx + dy * dy;
        if (d2 < R2) {
          const d = Math.sqrt(d2) + 1e-3, f = 1 - d / R, f2 = f * f * (3 - 2 * f);
          const core = Math.min(1, d / (R * 0.5));        // dots right under the finger stay put, so no hole opens at the pupil
          ax += push * f2 * core * dx / d + drag * ptr.vx * f2; ay += push * f2 * core * dy / d + drag * ptr.vy * f2;
        }
      }
      for (let i = 0; i < fr.length; i += 4) {
        const dx = rx[k] - fr[i], dy = ry[k] - fr[i + 1], d = Math.sqrt(dx * dx + dy * dy) + 1e-3, q = (d - fr[i + 2]) / RING_W;
        if (q > -3 && q < 3) { const g = Math.exp(-q * q) * fr[i + 3] * 420 / d; ax += g * dx; ay += g * dy; }
      }
      vx[k] += ax * dt; vy[k] += ay * dt; ox[k] += vx[k] * dt; oy[k] += vy[k] * dt;
    }
  }
  const RING_SPEED = 0.62, RING_LIFE = 1.25, RING_W = 13;  // speed in box-widths/s, life s, front width px
  const PR = () => Math.max(28, bw * 0.07);    // pointer radius

  // ---------- draw ----------
  const easeBack = u => { const c = 1.9; u -= 1; return 1 + (c + 1) * u * u * u + c * u * u; };
  function draw(still) {
    const GROW = 0.55, s = dpr, maxD = pitch * 1.0, pin = ptr.in, pR = PR(), pR2 = pR * pR;
    const kx = 6.2832 / (bh * 1.15), wt = 6.2832 / 9.0;           // idle ripple: long wavelength, 9 s period
    const fr = [];
    if (!still) for (const g of rings) { const age = T - g.t0; fr.push(g.x, g.y, age * RING_SPEED * bw, g.a * (1 - age / RING_LIFE) * Math.min(1, age * 12)); }
    for (let k = 0; k < N; k++) {
      let r = rBase[k], x = rx[k] + ox[k], y = ry[k] + oy[k];
      if (!still) {
        // a pushed dot thins as it travels, so the parted water stays light instead of piling into a black rim
        const disp = Math.sqrt(ox[k] * ox[k] + oy[k] * oy[k]);
        if (disp > 0.05) {
          r *= Math.max(0.75, 1 - disp / (pitch * 7));
          if (disp > maxD) { x = rx[k] + ox[k] * maxD / disp; y = ry[k] + oy[k] * maxD / disp; }   // nudge, never stream
        }
        if (pin) {                                                     // under the finger the dots swell a touch, like a loupe
          const dx = rx[k] - ptr.x, dy = ry[k] - ptr.y, d2 = dx * dx + dy * dy;
          if (d2 < pR2) { const f = 1 - Math.sqrt(d2 / pR2); r *= 1 + 0.12 * f * f * (3 - 2 * f); }
        }
        const age = T - delay[k];
        const u = Math.min(1, Math.max(0, age / GROW));
        const front = Math.exp(-(((age - 0.05) / 0.08) ** 2));       // wavefront: a ring of paper dots + a small outward lift
        const fl = front * lit[k];
        r = r * (u > 0 ? easeBack(u) : 0) + pitch * 0.13 * fl;
        x += edx[k] * 3.5 * fl; y += edy[k] * 3.5 * fl;
        // idle breath: two slow crossing swells, a few percent of each dot
        const ph = (rx[k] * 0.55 + ry[k]) * kx - T * wt, ph2 = (rx[k] - ry[k] * 0.35) * kx * 1.7 + T * wt * 0.63;
        r *= 1 + 0.045 * Math.sin(ph) + 0.022 * Math.sin(ph2);
        for (let i = 0; i < fr.length; i += 4) {
          const dx = rx[k] - fr[i], dy = ry[k] - fr[i + 1], q = (Math.sqrt(dx * dx + dy * dy) - fr[i + 2]) / RING_W;
          if (q > -3 && q < 3) { const g = Math.exp(-q * q) * fr[i + 3]; r = r * (1 + 0.38 * g) + pitch * 0.16 * g * lit[k]; }
        }
      }
      inst[3 * k] = x * s; inst[3 * k + 1] = y * s; inst[3 * k + 2] = Math.min(r, pitch * 0.95) * s;
    }
    gl.bindBuffer(gl.ARRAY_BUFFER, ib); gl.bufferSubData(gl.ARRAY_BUFFER, 0, inst);
    gl.enable(gl.SCISSOR_TEST);
    gl.scissor(Math.round(bx * s), Math.round((H - by - bh) * s), Math.round(bw * s), Math.round(bh * s));
    gl.clear(gl.COLOR_BUFFER_BIT);
    gl.drawArraysInstanced(gl.TRIANGLE_STRIP, 0, 4, N);
  }

  // ---------- loop / lifecycle ----------
  const rm = matchMedia('(prefers-reduced-motion: reduce)');
  let raf = 0, last = 0, visible = true;
  function frame(now) {
    raf = 0;
    let dt = last ? (now - last) / 1000 : 1 / 60; last = now;
    dt = Math.min(dt, DEBUG_WALL ? 0.25 : 1 / 20);                  // clamp: a slow frame is a slow frame, not a jump
    if (DEBUG_FREEZE) dt = Math.max(0, Math.min(dt, DEBUG_FREEZE - T));
    const n = Math.ceil(dt / (1 / 60) - 1e-6), h = n ? dt / n : 0;
    for (let i = 0; i < n; i++) { T += h; step(h); }
    draw(false);
    schedule();
  }
  function schedule() { if (!raf && visible && !document.hidden && !rm.matches) { raf = requestAnimationFrame(frame); } }
  function stop() { if (raf) cancelAnimationFrame(raf); raf = 0; last = 0; }
  function refresh() {
    if (rm.matches) { stop(); draw(true); }
    else if (document.hidden || !visible) stop();
    else schedule();
  }
  layout();
  if (rm.matches) draw(true); else { draw(false); schedule(); }
  new ResizeObserver(() => { if (layout() && (rm.matches || !raf)) draw(rm.matches); }).observe(el);
  new IntersectionObserver(es => { visible = es[es.length - 1].isIntersecting; refresh(); }).observe(el);
  document.addEventListener('visibilitychange', refresh);
  rm.addEventListener('change', refresh);
  el.addEventListener('pointermove', onMove);
  el.addEventListener('pointerdown', onMove);
  el.addEventListener('pointerleave', onLeave);
  el.addEventListener('pointercancel', onLeave);
}
